public class Account {
    private final String accountId;
    private long balance;        // whole rupees
    private long dailyUsed;
    public Account(String accountId, long balance) {
        this.accountId = accountId; this.balance = balance;
    }
    public long getBalance() { return balance; }
    public long getDailyUsed() { return dailyUsed; }
    void setBalance(long b) { balance = b; }
    void setDailyUsed(long d) { dailyUsed = d; }
}

public class InMemoryBankService implements BankService {
    private static final long DAILY_LIMIT = 25_000;
    private final Map<String, Account> accounts = new ConcurrentHashMap<>();
    private final Map<String, String> pins = new ConcurrentHashMap<>();

    public void addAccount(Account acc, String cardNumber, String pin) {
        accounts.put(acc.getAccountId(), acc);
        pins.put(cardNumber, pin);
    }
    public boolean verifyPin(Card card, String pin) {
        return pin.equals(pins.get(card.getCardNumber()));
    }
    public long getBalance(String accountId) { return accounts.get(accountId).getBalance(); }

    public synchronized void debit(String accountId, long amount) {
        Account acc = accounts.get(accountId);
        if (acc.getBalance() < amount) throw new InsufficientBalanceException();
        if (acc.getDailyUsed() + amount > DAILY_LIMIT) throw new DailyLimitExceededException();
        acc.setBalance(acc.getBalance() - amount);      // atomic check and change
        acc.setDailyUsed(acc.getDailyUsed() + amount);
    }
    public synchronized void credit(String accountId, long amount) {
        Account acc = accounts.get(accountId);
        acc.setBalance(acc.getBalance() + amount);
    }
}

