public: DailyLimitExceededException() : std::runtime_error("daily limit exceeded") {}
};

class Card {
public:
    Card(std::string cardNumber, std::string accountId, std::chrono::system_clock::time_point expiry)
        : cardNumber_(std::move(cardNumber)), accountId_(std::move(accountId)), expiry_(expiry) {}
    const std::string& getCardNumber() const { return cardNumber_; }
    const std::string& getAccountId() const { return accountId_; }
    bool isExpired() const { return expiry_ < std::chrono::system_clock::now(); }

private:
    std::string cardNumber_, accountId_;
    std::chrono::system_clock::time_point expiry_;
};

class Account {
public:
    Account(std::string accountId, long balance) : accountId_(std::move(accountId)), balance_(balance) {}
    const std::string& getAccountId() const { return accountId_; }
    long getBalance() const { return balance_; }
    long getDailyUsed() const { return dailyUsed_; }
    void setBalance(long b) { balance_ = b; }
    void setDailyUsed(long d) { dailyUsed_ = d; }

private:
    std::string accountId_;
    long balance_;
    long dailyUsed_ = 0;
};

class InMemoryBankService {
public:
    static constexpr long DAILY_LIMIT = 25000;

    void addAccount(Account acc, const std::string& cardNumber, const std::string& pin) {
        std::string id = acc.getAccountId();
        accounts_.emplace(id, std::move(acc));
        pins_[cardNumber] = pin;
    }
    bool verifyPin(const Card& card, const std::string& pin) {
        auto it = pins_.find(card.getCardNumber());
        return it != pins_.end() && it->second == pin;
    }
    long getBalance(const std::string& accountId) { return accounts_.at(accountId).getBalance(); }

    void debit(const std::string& accountId, long amount) {
        std::lock_guard<std::mutex> lock(mutex_);
        Account& acc = accounts_.at(accountId);
        if (acc.getBalance() < amount) throw InsufficientBalanceException();
        if (acc.getDailyUsed() + amount > DAILY_LIMIT) throw DailyLimitExceededException();
        acc.setBalance(acc.getBalance() - amount);      // atomic check and change
        acc.setDailyUsed(acc.getDailyUsed() + amount);
    }
    void credit(const std::string& accountId, long amount) {
        std::lock_guard<std::mutex> lock(mutex_);
        Account& acc = accounts_.at(accountId);
        acc.setBalance(acc.getBalance() + amount);
    }

private:
    std::map<std::string, Account> accounts_;
    std::map<std::string, std::string> pins_;
    std::mutex mutex_;
};

