class Card:
    def __init__(self, card_number: str, account_id: str, expiry: date):
        self._card_number = card_number
        self._account_id = account_id
        self._expiry = expiry

    def get_card_number(self) -> str: return self._card_number
    def get_account_id(self) -> str: return self._account_id
