    def get_balance(self) -> int: return self._balance
    def get_daily_used(self) -> int: return self._daily_used
    def set_balance(self, b: int) -> None: self._balance = b
    def set_daily_used(self, d: int) -> None: self._daily_used = d


class InMemoryBankService:
    DAILY_LIMIT = 25_000

    def __init__(self):
        self._accounts: Dict[str, Account] = {}
        self._pins: Dict[str, str] = {}
        self._lock = threading.Lock()

    def add_account(self, acc: Account, card_number: str, pin: str) -> None:
        self._accounts[acc.get_account_id()] = acc
        self._pins[card_number] = pin

