public abstract class NoteHandler {
    private final int noteValue;
    private int count;
    private NoteHandler next;

    protected NoteHandler(int noteValue, int count) {
        this.noteValue = noteValue; this.count = count;
    }
    public NoteHandler linkNext(NoteHandler next) { this.next = next; return next; }
    public void refill(int more) { count += more; }

    // plan without committing: how many of each note would we give?
    public boolean plan(long amount, Map<Integer, Integer> out) {
        int use = (int) Math.min(amount / noteValue, count);
        if (use > 0) out.put(noteValue, use);
        long remaining = amount - (long) use * noteValue;
        if (remaining == 0) return true;
        if (next != null) return next.plan(remaining, out);
        return false;                                   // chain cannot cover it
    }
    public void commit(Map<Integer, Integer> plan) {
        count -= plan.getOrDefault(noteValue, 0);       // deduct this cassette
        if (next != null) next.commit(plan);
    }
}

public class Note2000Handler extends NoteHandler { public Note2000Handler(int c) { super(2000, c); } }
public class Note500Handler  extends NoteHandler { public Note500Handler(int c)  { super(500, c); } }
public class Note100Handler  extends NoteHandler { public Note100Handler(int c)  { super(100, c); } }

public class CashDispenser {
    private final NoteHandler chain;
    public CashDispenser(NoteHandler chain) { this.chain = chain; }

    public synchronized boolean canDispense(long amount) {
        return amount > 0 && amount % 100 == 0 && chain.plan(amount, new HashMap<>());
    }
    public synchronized Map<Integer, Integer> dispense(long amount) {
        Map<Integer, Integer> plan = new HashMap<>();
        if (!chain.plan(amount, plan)) throw new InsufficientCashException();
        chain.commit(plan);                             // deduct cassettes atomically
        return plan;                                    // e.g. {2000:1, 500:3}
    }
}

