#include <algorithm>
#include <map>
#include <stdexcept>

class InsufficientCashException : public std::runtime_error {
public: InsufficientCashException() : std::runtime_error("insufficient cash") {}
};

class NoteHandler {
public:
    NoteHandler(int noteValue, int count) : noteValue_(noteValue), count_(count) {}
    virtual ~NoteHandler() = default;

    NoteHandler* linkNext(NoteHandler* next) { next_ = next; return next; }
    void refill(int more) { count_ += more; }

    // plan without committing: how many of each note would we give?
    bool plan(long amount, std::map<int, int>& out) {
        int use = static_cast<int>(std::min<long>(amount / noteValue_, count_));
        if (use > 0) out[noteValue_] = use;
        long remaining = amount - static_cast<long>(use) * noteValue_;
        if (remaining == 0) return true;
        if (next_ != nullptr) return next_->plan(remaining, out);
        return false;                                    // chain cannot cover it
    }
    void commit(const std::map<int, int>& plan) {
        auto it = plan.find(noteValue_);
        count_ -= (it != plan.end() ? it->second : 0);   // deduct this cassette
        if (next_ != nullptr) next_->commit(plan);
    }

protected:
    int noteValue_;
    int count_;
    NoteHandler* next_ = nullptr;
};

class Note2000Handler : public NoteHandler { public: explicit Note2000Handler(int c) : NoteHandler(2000, c) {} };
class Note500Handler  : public NoteHandler { public: explicit Note500Handler(int c)  : NoteHandler(500, c)  {} };
class Note100Handler  : public NoteHandler { public: explicit Note100Handler(int c)  : NoteHandler(100, c)  {} };

class CashDispenser {
public:
    explicit CashDispenser(NoteHandler* chain) : chain_(chain) {}

    bool canDispense(long amount) {
        std::map<int, int> scratch;
        return amount > 0 && amount % 100 == 0 && chain_->plan(amount, scratch);
    }
    std::map<int, int> dispense(long amount) {
        std::map<int, int> plan;
        if (!chain_->plan(amount, plan)) throw InsufficientCashException();
        chain_->commit(plan);          // deduct cassettes atomically
        return plan;                    // e.g. {2000: 1, 500: 3}
    }

private:
    NoteHandler* chain_;
};

