from typing import Dict, Optional


class InsufficientCashException(Exception): pass


class NoteHandler:
    def __init__(self, note_value: int, count: int):
        self._note_value = note_value
        self._count = count
        self._next: Optional["NoteHandler"] = None

    def link_next(self, next_handler: "NoteHandler") -> "NoteHandler":
        self._next = next_handler
        return next_handler

    def refill(self, more: int) -> None:
        self._count += more

    # plan without committing: how many of each note would we give?
    def plan(self, amount: int, out: Dict[int, int]) -> bool:
        use = min(amount // self._note_value, self._count)
        if use > 0:
            out[self._note_value] = use
        remaining = amount - use * self._note_value
        if remaining == 0:
            return True
        if self._next is not None:
            return self._next.plan(remaining, out)
        return False                                   # chain cannot cover it

    def commit(self, plan: Dict[int, int]) -> None:
        self._count -= plan.get(self._note_value, 0)    # deduct this cassette
        if self._next is not None:
            self._next.commit(plan)


class Note2000Handler(NoteHandler):
    def __init__(self, count: int): super().__init__(2000, count)


class Note500Handler(NoteHandler):
    def __init__(self, count: int): super().__init__(500, count)


class Note100Handler(NoteHandler):
    def __init__(self, count: int): super().__init__(100, count)


class CashDispenser:
    def __init__(self, chain: NoteHandler):
        self._chain = chain

    def can_dispense(self, amount: int) -> bool:
        return amount > 0 and amount % 100 == 0 and self._chain.plan(amount, {})

    def dispense(self, amount: int) -> Dict[int, int]:
        plan: Dict[int, int] = {}
        if not self._chain.plan(amount, plan):
            raise InsufficientCashException()
        self._chain.commit(plan)         # deduct cassettes atomically
        return plan                       # e.g. {2000: 1, 500: 3}

