public class IdleState implements ATMState {
    public void insertCard(ATM atm, Card card) {
        if (card.isExpired()) throw new CardExpiredException();
        atm.setCard(card);
        atm.setState(new CardInsertedState());
    }
    public void enterPin(ATM atm, String pin) { throw new IllegalStateException("Insert a card first"); }
    public void withdraw(ATM atm, long amount) { throw new IllegalStateException("Insert a card first"); }
    public void checkBalance(ATM atm) { throw new IllegalStateException("Insert a card first"); }
    public void ejectCard(ATM atm) { throw new IllegalStateException("No card inside"); }
}

public class CardInsertedState implements ATMState {
    private int attempts = 0;
    public void insertCard(ATM atm, Card card) { throw new IllegalStateException("A card is already inside"); }
    public void enterPin(ATM atm, String pin) {
        if (atm.getBank().verifyPin(atm.getCard(), pin)) {
            atm.setState(new AuthenticatedState());
            return;
        }
        attempts++;
        if (attempts >= 3) {                       // retain the card, protect the account
            atm.retainCard();
            atm.setState(new IdleState());
            throw new CardBlockedException();
        }
        throw new InvalidPinException(3 - attempts);
    }
    public void withdraw(ATM atm, long amount) { throw new IllegalStateException("Enter your PIN first"); }
    public void checkBalance(ATM atm) { throw new IllegalStateException("Enter your PIN first"); }
    public void ejectCard(ATM atm) { atm.returnCard(); atm.setState(new IdleState()); }
}

public class AuthenticatedState implements ATMState {
    public void insertCard(ATM atm, Card card) { throw new IllegalStateException("Session in progress"); }
    public void enterPin(ATM atm, String pin) { throw new IllegalStateException("Already authenticated"); }
    public void withdraw(ATM atm, long amount) {
        if (amount <= 0 || amount % 100 != 0) throw new InvalidAmountException(amount);
        if (!atm.getDispenser().canDispense(amount))    // cash first, bank second
            throw new InsufficientCashException();
        atm.getBank().debit(atm.getCard().getAccountId(), amount);
        atm.setPendingAmount(amount);
        atm.setState(new DispensingState());
        atm.dispense();                                  // continue immediately
    }
    public void checkBalance(ATM atm) {
        long bal = atm.getBank().getBalance(atm.getCard().getAccountId());
        atm.display("Balance: " + bal);
    }
    public void ejectCard(ATM atm) { atm.returnCard(); atm.setState(new IdleState()); }
}

public class DispensingState implements ATMState {
    public void insertCard(ATM atm, Card card) { throw new IllegalStateException("Dispensing in progress"); }
    public void enterPin(ATM atm, String pin) { throw new IllegalStateException("Dispensing in progress"); }
    public void withdraw(ATM atm, long amount) { throw new IllegalStateException("Dispensing in progress"); }
    public void checkBalance(ATM atm) { throw new IllegalStateException("Dispensing in progress"); }
    public void ejectCard(ATM atm) {
        Map<Integer, Integer> notes = atm.getDispenser().dispense(atm.getPendingAmount());
        atm.display("Dispensed: " + notes);
        atm.returnCard();
        atm.setState(new IdleState());
    }
}

