class InvalidPinException(Exception):
    def __init__(self, attempts_left: int): super().__init__(f"{attempts_left} attempts left")


class InvalidAmountException(Exception):
    def __init__(self, amount: int): super().__init__(f"invalid amount {amount}")


class ATMState:                                   # full interface shown in an earlier block
    def insert_card(self, atm: "ATM", card: "Card") -> None: ...
    def enter_pin(self, atm: "ATM", pin: str) -> None: ...
    def withdraw(self, atm: "ATM", amount: int) -> None: ...
    def check_balance(self, atm: "ATM") -> None: ...
    def eject_card(self, atm: "ATM") -> None: ...


class IdleState(ATMState):
    def insert_card(self, atm, card):
        if card.is_expired():
            raise CardExpiredException()
        atm.set_card(card)
        atm.set_state(CardInsertedState())

    def enter_pin(self, atm, pin): raise RuntimeError("Insert a card first")
    def withdraw(self, atm, amount): raise RuntimeError("Insert a card first")
    def check_balance(self, atm): raise RuntimeError("Insert a card first")
    def eject_card(self, atm): raise RuntimeError("No card inside")


class CardInsertedState(ATMState):
    def __init__(self):
        self._attempts = 0

    def insert_card(self, atm, card): raise RuntimeError("A card is already inside")

    def enter_pin(self, atm, pin):
        if atm.get_bank().verify_pin(atm.get_card(), pin):
            atm.set_state(AuthenticatedState())
            return
        self._attempts += 1
        if self._attempts >= 3:                # retain the card, protect the account
            atm.retain_card()
            atm.set_state(IdleState())
            raise CardBlockedException()
        raise InvalidPinException(3 - self._attempts)

    def withdraw(self, atm, amount): raise RuntimeError("Enter your PIN first")
    def check_balance(self, atm): raise RuntimeError("Enter your PIN first")
    def eject_card(self, atm):
        atm.return_card()
        atm.set_state(IdleState())


class AuthenticatedState(ATMState):
    def insert_card(self, atm, card): raise RuntimeError("Session in progress")
    def enter_pin(self, atm, pin): raise RuntimeError("Already authenticated")

    def withdraw(self, atm, amount):
        if amount <= 0 or amount % 100 != 0:
            raise InvalidAmountException(amount)
        if not atm.get_dispenser().can_dispense(amount):    # cash first, bank second
            raise InsufficientCashException()
        atm.get_bank().debit(atm.get_card().get_account_id(), amount)
        atm.set_pending_amount(amount)
        atm.set_state(DispensingState())
        atm.dispense()                                       # continue immediately

    def check_balance(self, atm):
        bal = atm.get_bank().get_balance(atm.get_card().get_account_id())
        atm.display(f"Balance: {bal}")

    def eject_card(self, atm):
        atm.return_card()
        atm.set_state(IdleState())


class DispensingState(ATMState):
    def insert_card(self, atm, card): raise RuntimeError("Dispensing in progress")
    def enter_pin(self, atm, pin): raise RuntimeError("Dispensing in progress")
    def withdraw(self, atm, amount): raise RuntimeError("Dispensing in progress")
    def check_balance(self, atm): raise RuntimeError("Dispensing in progress")

    def eject_card(self, atm):
        notes = atm.get_dispenser().dispense(atm.get_pending_amount())
        atm.display(f"Dispensed: {notes}")
        atm.return_card()
        atm.set_state(IdleState())

