class ATM {
public:
    ATM(BankService* bank, CashDispenser* dispenser)
        : state_(std::make_shared<IdleState>()), bank_(bank), dispenser_(dispenser) {}

    // customer facing, all delegated to the current state
    void insertCard(const Card& c) { state_->insertCard(*this, c); }
    void enterPin(const std::string& pin) { state_->enterPin(*this, pin); }
    void withdraw(long amount) { state_->withdraw(*this, amount); }
    void checkBalance() { state_->checkBalance(*this); }
    void ejectCard() { state_->ejectCard(*this); }
    void dispense() { state_->ejectCard(*this); }          // DispensingState completes here

    // callbacks used by states
    void setState(std::shared_ptr<ATMState> s) { state_ = std::move(s); }
    void setCard(const Card& c) { card_ = std::make_shared<Card>(c); }
    Card& getCard() { return *card_; }
    BankService& getBank() { return *bank_; }
    CashDispenser& getDispenser() { return *dispenser_; }
    void setPendingAmount(long a) { pendingAmount_ = a; }
    long getPendingAmount() const { return pendingAmount_; }
    void returnCard() { display("Card returned"); card_ = nullptr; pendingAmount_ = 0; }
    void retainCard() { display("Card retained"); card_ = nullptr; pendingAmount_ = 0; }
    void display(const std::string& msg) { std::cout << msg << "\n"; }

private:
    std::shared_ptr<ATMState> state_;
    BankService* bank_;
    CashDispenser* dispenser_;
    std::shared_ptr<Card> card_;
    long pendingAmount_ = 0;
};

void IdleState::insertCard(ATM& atm, const Card& card) {
    if (card.isExpired()) throw CardExpiredException();
    atm.setCard(card);
    atm.setState(std::make_shared<CardInsertedState>());
}
void CardInsertedState::enterPin(ATM& atm, const std::string& pin) {
    if (atm.getBank().verifyPin(atm.getCard(), pin)) { atm.setState(std::make_shared<AuthenticatedState>()); return; }
    attempts_++;
    if (attempts_ >= 3) { atm.retainCard(); atm.setState(std::make_shared<IdleState>()); throw CardBlockedException(); }
    throw InvalidPinException(3 - attempts_);
}
void CardInsertedState::ejectCard(ATM& atm) { atm.returnCard(); atm.setState(std::make_shared<IdleState>()); }

void AuthenticatedState::withdraw(ATM& atm, long amount) {
    if (amount <= 0 || amount % 100 != 0) throw InvalidAmountException(amount);
    if (!atm.getDispenser().canDispense(amount)) throw InsufficientCashException();
    atm.getBank().debit(atm.getCard().getAccountId(), amount);
    atm.setPendingAmount(amount);
    atm.setState(std::make_shared<DispensingState>());
    atm.dispense();
}
void AuthenticatedState::checkBalance(ATM& atm) {
    long bal = atm.getBank().getBalance(atm.getCard().getAccountId());
    atm.display("Balance: " + std::to_string(bal));
}
void AuthenticatedState::ejectCard(ATM& atm) { atm.returnCard(); atm.setState(std::make_shared<IdleState>()); }

void DispensingState::ejectCard(ATM& atm) {
    auto notes = atm.getDispenser().dispense(atm.getPendingAmount());
    atm.display("Dispensed: notes ready");
    atm.returnCard();
    atm.setState(std::make_shared<IdleState>());
}

